<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Laporan Pengeluaran</title><style>body{font:13px Arial,sans-serif;color:#111827;margin:24px}h1{margin:0 0 6px;font-size:20px}p{margin:0 0 18px;color:#4b5563}table{width:100%;border-collapse:collapse}th,td{border:1px solid #d1d5db;padding:8px;text-align:left}th{background:#f3f4f6}td.amount,th.amount{text-align:right}.total{font-weight:bold}@media print{.toolbar{display:none}body{margin:0}}</style></head><body><div class="toolbar" style="margin-bottom:16px"><button onclick="window.print()">Cetak</button></div><h1>Laporan Pengeluaran</h1><p>Dicetak {{ now()->format('d M Y H:i') }}@if($filters['date_from'] ?? false) · Dari {{ $filters['date_from'] }}@endif @if($filters['date_to'] ?? false) sampai {{ $filters['date_to'] }}@endif</p><table><thead><tr><th>Tanggal</th><th>Kode</th><th>Kategori</th><th>Keterangan</th><th>Metode</th><th class="amount">Nominal</th></tr></thead><tbody>@forelse($expenses as $expense)<tr><td>{{ $expense->tanggal?->format('d M Y') }}</td><td>{{ $expense->kode_beban }}</td><td>{{ str_replace('_', ' ', $expense->kategori_beban) }}</td><td>{{ $expense->keterangan }}</td><td>{{ $expense->metode_bayar }}</td><td class="amount">Rp {{ number_format((float)$expense->nominal, 0, ',', '.') }}</td></tr>@empty<tr><td colspan="6">Tidak ada data.</td></tr>@endforelse</tbody><tfoot><tr class="total"><td colspan="5">Total Pengeluaran</td><td class="amount">Rp {{ number_format((float)$total, 0, ',', '.') }}</td></tr></tfoot></table><script>window.addEventListener('load',()=>window.print())</script></body></html>
